  lregs R w -> getr R (reg 25) = Z_to_bv 64 d -> 0 <= d <= w -> d <= PM.CHUNK -> 1 <= w <= len ->
  st_ok M model src x g sm cr LK Aw -> acct src x g sm (w - d) -> PM.mu_src src sm < mu0 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0xd5310 M model) K.
